16	import { BackstageCredentials } from '@backstage/backend-plugin-api';
17	import { Server as McpServer } from '@modelcontextprotocol/sdk/server/index.js';
18	import {
19	  ListToolsRequestSchema,
20	  CallToolRequestSchema,
21	} from '@modelcontextprotocol/sdk/types.js';
22	import { JsonObject } from '@backstage/types';
23	import {
24	  ActionsService,
25	  MetricsServiceHistogram,
26	  MetricsService,
27	} from '@backstage/backend-plugin-api/alpha';
28	import { version } from '@backstage/plugin-mcp-actions-backend/package.json';
29	import { NotFoundError } from '@backstage/errors';
30	import { performance } from 'node:perf_hooks';
31	
32	import { handleErrors } from './handleErrors';
33	import { bucketBoundaries, McpServerOperationAttributes } from '../metrics';
34	
35	export class McpService {
36	  private readonly actions: ActionsService;
37	  private readonly operationDuration: MetricsServiceHistogram<McpServerOperationAttributes>;
38	
39	  constructor(actions: ActionsService, metrics: MetricsService) {
40	    this.actions = actions;
41	    this.operationDuration =
42	      metrics.createHistogram<McpServerOperationAttributes>(
43	        'mcp.server.operation.duration',
44	        {
45	          description: 'MCP request duration as observed on the receiver',
46	          unit: 's',
47	          advice: { explicitBucketBoundaries: bucketBoundaries },
48	        },
49	      );
50	  }
51	
52	  static async create({
53	    actions,
54	    metrics,
55	  }: {
56	    actions: ActionsService;
57	    metrics: MetricsService;
58	  }) {
59	    return new McpService(actions, metrics);
60	  }
61	
62	  getServer({ credentials }: { credentials: BackstageCredentials }) {
63	    const server = new McpServer(
64	      {
65	        name: 'backstage',
66	        // TODO: this version will most likely change in the future.
67	        version,
68	      },
69	      { capabilities: { tools: {} } },
70	    );
71	
72	    server.setRequestHandler(ListToolsRequestSchema, async () => {
73	      const startTime = performance.now();
74	      let errorType: string | undefined;
75	
76	      try {
77	        // TODO: switch this to be configuration based later
78	        const { actions } = await this.actions.list({ credentials });
79	
80	        return {
81	          tools: actions.map(action => ({
82	            inputSchema: action.schema.input,
83	            // todo(blam): this is unfortunately not supported by most clients yet.
84	            // When this is provided you need to provide structuredContent instead.
85	            // outputSchema: action.schema.output,
86	            name: action.name,
87	            description: action.description,
88	            annotations: {
89	              title: action.title,
90	              destructiveHint: action.attributes.destructive,
91	              idempotentHint: action.attributes.idempotent,
92	              readOnlyHint: action.attributes.readOnly,
93	              openWorldHint: false,
94	            },
95	          })),
96	        };
97	      } catch (err) {
98	        errorType = err instanceof Error ? err.name : 'Error';
99	        throw err;
100	      } finally {
101	        const durationSeconds = (performance.now() - startTime) / 1000;
102	
103	        this.operationDuration.record(durationSeconds, {
104	          'mcp.method.name': 'tools/list',
105	          ...(errorType && { 'error.type': errorType }),
106	        });
107	      }
108	    });
109	
110	    server.setRequestHandler(CallToolRequestSchema, async ({ params }) => {
111	      const startTime = performance.now();
112	      let errorType: string | undefined;
113	      let isError = false;
114	
115	      try {
116	        const result = await handleErrors(async () => {
117	          const { actions } = await this.actions.list({ credentials });
118	          const action = actions.find(a => a.name === params.name);
119	
120	          if (!action) {
121	            throw new NotFoundError(`Action "${params.name}" not found`);
122	          }
123	
124	          const { output } = await this.actions.invoke({
125	            id: action.id,
126	            input: params.arguments as JsonObject,
127	            credentials,
128	          });
129	
130	          return {
131	            // todo(blam): unfortunately structuredContent is not supported by most clients yet.
132	            // so the validation for the output happens in the default actions registry
133	            // and we return it as json text instead for now.
134	            content: [
135	              {
136	                type: 'text',
137	                text: ['```json', JSON.stringify(output, null, 2), '```'].join(
138	                  '\n',
139	                ),
140	              },
141	            ],
142	          };
143	        });
144	
145	        isError = !!(result as { isError?: boolean })?.isError;
146	        return result;
147	      } catch (err) {
148	        errorType = err instanceof Error ? err.name : 'Error';
149	        throw err;
150	      } finally {
151	        const durationSeconds = (performance.now() - startTime) / 1000;
152	
153	        // Determine error.type per OTel MCP spec:
154	        // - Thrown exceptions use the error name
155	        // - CallToolResult with isError=true uses 'tool_error'
156	        let errorAttribute: string | undefined = errorType;
157	        if (!errorAttribute && isError) {
158	          errorAttribute = 'tool_error';
159	        }
160	
161	        this.operationDuration.record(durationSeconds, {
162	          'mcp.method.name': 'tools/call',
163	          'gen_ai.tool.name': params.name,
164	          'gen_ai.operation.name': 'execute_tool',
165	          ...(errorAttribute && { 'error.type': errorAttribute }),
166	        });
167	      }
168	    });
169	
170	    return server;
171	  }
172	}
173

