16	import {
17	  coreServices,
18	  createBackendPlugin,
19	} from '@backstage/backend-plugin-api';
20	import { json } from 'express';
21	import Router from 'express-promise-router';
22	import { McpService } from './services/McpService';
23	import { createStreamableRouter } from './routers/createStreamableRouter';
24	import { createSseRouter } from './routers/createSseRouter';
25	import {
26	  actionsRegistryServiceRef,
27	  actionsServiceRef,
28	  metricsServiceRef,
29	} from '@backstage/backend-plugin-api/alpha';
30	
31	/**
32	 * mcpPlugin backend plugin
33	 *
34	 * @public
35	 */
36	export const mcpPlugin = createBackendPlugin({
37	  pluginId: 'mcp-actions',
38	  register(env) {
39	    env.registerInit({
40	      deps: {
41	        logger: coreServices.logger,
42	        auth: coreServices.auth,
43	        httpAuth: coreServices.httpAuth,
44	        httpRouter: coreServices.httpRouter,
45	        actions: actionsServiceRef,
46	        registry: actionsRegistryServiceRef,
47	        rootRouter: coreServices.rootHttpRouter,
48	        discovery: coreServices.discovery,
49	        config: coreServices.rootConfig,
50	        metrics: metricsServiceRef,
51	      },
52	      async init({
53	        actions,
54	        logger,
55	        httpRouter,
56	        httpAuth,
57	        rootRouter,
58	        discovery,
59	        config,
60	        metrics,
61	      }) {
62	        const mcpService = await McpService.create({
63	          actions,
64	          metrics,
65	        });
66	
67	        const sseRouter = createSseRouter({
68	          mcpService,
69	          httpAuth,
70	        });
71	
72	        const streamableRouter = createStreamableRouter({
73	          mcpService,
74	          httpAuth,
75	          logger,
76	          metrics,
77	        });
78	
79	        const router = Router();
80	        router.use(json());
81	
82	        router.use('/v1/sse', sseRouter);
83	        router.use('/v1', streamableRouter);
84	
85	        httpRouter.use(router);
86	
87	        const oauthEnabled =
88	          config.getOptionalBoolean(
89	            'auth.experimentalDynamicClientRegistration.enabled',
90	          ) ||
91	          config.getOptionalBoolean(
92	            'auth.experimentalClientIdMetadataDocuments.enabled',
93	          );
94	
95	        if (oauthEnabled) {
96	          // OAuth Authorization Server Metadata (RFC 8414)
97	          // This should be replaced with throwing a WWW-Authenticate header, but that doesn't seem to be supported by
98	          // many of the MCP clients as of yet. So this seems to be the oldest version of the spec that's implemented.
99	          rootRouter.use(
100	            '/.well-known/oauth-authorization-server',
101	            async (_, res) => {
102	              const authBaseUrl = await discovery.getBaseUrl('auth');
103	              const oidcResponse = await fetch(
104	                `${authBaseUrl}/.well-known/openid-configuration`,
105	              );
106	              res.json(await oidcResponse.json());
107	            },
108	          );
109	
110	          // Protected Resource Metadata (RFC 9728)
111	          // https://datatracker.ietf.org/doc/html/rfc9728
112	          // This allows MCP clients to discover the authorization server for this resource
113	          rootRouter.use(
114	            '/.well-known/oauth-protected-resource',
115	            async (_, res) => {
116	              const [authBaseUrl, mcpBaseUrl] = await Promise.all([
117	                discovery.getBaseUrl('auth'),
118	                discovery.getBaseUrl('mcp-actions'),
119	              ]);
120	              res.json({
121	                resource: mcpBaseUrl,
122	                authorization_servers: [authBaseUrl],
123	              });
124	            },
125	          );
126	        }
127	      },
128	    });
129	  },
130	});
