16	import PromiseRouter from 'express-promise-router';
17	import { Router } from 'express';
18	import { performance } from 'node:perf_hooks';
19	import { McpService } from '../services/McpService';
20	import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
21	import { LATEST_PROTOCOL_VERSION } from '@modelcontextprotocol/sdk/types.js';
22	import { HttpAuthService, LoggerService } from '@backstage/backend-plugin-api';
23	import { isError } from '@backstage/errors';
24	import { MetricsService } from '@backstage/backend-plugin-api/alpha';
25	import { bucketBoundaries, McpServerSessionAttributes } from '../metrics';
26	
27	export const createStreamableRouter = ({
28	  mcpService,
29	  httpAuth,
30	  logger,
31	  metrics,
32	}: {
33	  mcpService: McpService;
34	  logger: LoggerService;
35	  httpAuth: HttpAuthService;
36	  metrics: MetricsService;
37	}): Router => {
38	  const router = PromiseRouter();
39	
40	  const sessionDuration = metrics.createHistogram<McpServerSessionAttributes>(
41	    'mcp.server.session.duration',
42	    {
43	      description:
44	        'The duration of the MCP session as observed on the MCP server',
45	      unit: 's',
46	      advice: { explicitBucketBoundaries: bucketBoundaries },
47	    },
48	  );
49	
50	  router.post('/', async (req, res) => {
51	    const sessionStart = performance.now();
52	
53	    const baseAttributes: McpServerSessionAttributes = {
54	      'mcp.protocol.version': LATEST_PROTOCOL_VERSION,
55	      'network.transport': 'tcp',
56	      'network.protocol.name': 'http',
57	    };
58	
59	    try {
60	      const server = mcpService.getServer({
61	        credentials: await httpAuth.credentials(req),
62	      });
63	
64	      const transport = new StreamableHTTPServerTransport({
65	        // stateless implementation for now, so that we can support multiple
66	        // instances of the server backend, and avoid sticky sessions.
67	        sessionIdGenerator: undefined,
68	      });
69	
70	      await server.connect(transport);
71	      await transport.handleRequest(req, res, req.body);
72	
73	      res.on('close', () => {
74	        transport.close();
75	        server.close();
76	
77	        const durationSeconds = (performance.now() - sessionStart) / 1000;
78	
79	        sessionDuration.record(durationSeconds, baseAttributes);
80	      });
81	    } catch (error) {
82	      const errorType = isError(error) ? error.name : 'Error';
83	
84	      if (isError(error)) {
85	        logger.error(error.message);
86	      }
87	
88	      if (!res.headersSent) {
89	        res.status(500).json({
90	          jsonrpc: '2.0',
91	          error: {
92	            code: -32603,
93	            message: 'Internal server error',
94	          },
95	          id: null,
96	        });
97	      }
98	
99	      const durationSeconds = (performance.now() - sessionStart) / 1000;
100	
101	      sessionDuration.record(durationSeconds, {
102	        ...baseAttributes,
103	        'error.type': errorType,
104	      });
105	    }
106	  });
107	
108	  router.get('/', async (_, res) => {
109	    // We only support POST requests, so we return a 405 error for all other methods.
110	    res.writeHead(405).end(
111	      JSON.stringify({
112	        jsonrpc: '2.0',
113	        error: {
114	          code: -32000,
115	          message: 'Method not allowed.',
116	        },
117	        id: null,
118	      }),
119	    );
120	  });
121	
122	  router.delete('/', async (_, res) => {
123	    // We only support POST requests, so we return a 405 error for all other methods.
124	    res.writeHead(405).end(
125	      JSON.stringify({
126	        jsonrpc: '2.0',
127	        error: {
128	          code: -32000,
129	          message: 'Method not allowed.',
130	        },
131	        id: null,
132	      }),
133	    );
134	  });
135	
136	  return router;
137	};
