16	import PromiseRouter from 'express-promise-router';
17	import { Router } from 'express';
18	import { McpService } from '../services/McpService';
19	import { SSEServerTransport } from '@modelcontextprotocol/sdk/server/sse.js';
20	import { HttpAuthService } from '@backstage/backend-plugin-api';
21	
22	/**
23	 * Legacy SSE endpoint for older clients, hopefully will not be needed for much longer.
24	 */
25	export const createSseRouter = ({
26	  mcpService,
27	  httpAuth,
28	}: {
29	  mcpService: McpService;
30	  httpAuth: HttpAuthService;
31	}): Router => {
32	  const router = PromiseRouter();
33	  const transportsToSessionId = new Map<string, SSEServerTransport>();
34	
35	  router.get('/', async (req, res) => {
36	    const server = mcpService.getServer({
37	      credentials: await httpAuth.credentials(req),
38	    });
39	
40	    const transport = new SSEServerTransport(
41	      `${req.originalUrl}/messages`,
42	      res,
43	    );
44	
45	    transportsToSessionId.set(transport.sessionId, transport);
46	
47	    res.on('close', () => {
48	      transportsToSessionId.delete(transport.sessionId);
49	    });
50	
51	    await server.connect(transport);
52	  });
53	
54	  router.post('/messages', async (req, res) => {
55	    const sessionId = req.query.sessionId as string;
56	
57	    if (!sessionId) {
58	      res.status(400).contentType('text/plain').write('sessionId is required');
59	      return;
60	    }
61	
62	    const transport = transportsToSessionId.get(sessionId);
63	    if (transport) {
64	      await transport.handlePostMessage(req, res, req.body);
65	    } else {
66	      res
67	        .status(400)
68	        .contentType('text/plain')
69	        .write(`No transport found for sessionId "${sessionId}"`);
70	    }
71	  });
72	  return router;
73	};
