import { Config } from '@backstage/config';
import { ActionsServiceAction } from '@backstage/backend-plugin-api/alpha';

/**
 * A single filter rule that can match actions by ID (with glob pattern
 * support) and/or by attributes such as destructive, readOnly, and idempotent.
 */
export type FilterRule = {
  id?: string;
  attributes?: {
    destructive?: boolean;
    readOnly?: boolean;
    idempotent?: boolean;
  };
};

/**
 * Configuration for a named MCP server, specifying a display name and
 * include/exclude filter rules for scoping available actions.
 */
export type McpServerConfig = {
  name: string;
  includeRules: FilterRule[];
  excludeRules: FilterRule[];
};

/**
 * Parses a config array (as returned by {@link Config.getConfigArray}) into an
 * array of {@link FilterRule} objects. Supports id patterns with glob syntax
 * and attribute conditions.
 */
export function parseFilterRules(configs: Config[]): FilterRule[] {
  return configs.map(config => {
    const rule: FilterRule = {};

    const id = config.getOptionalString('id');
    if (id !== undefined) {
      rule.id = id;
    }

    const attributes = config.getOptionalConfig('attributes');
    if (attributes) {
      const parsedAttributes: NonNullable<FilterRule['attributes']> = {};

      const destructive = attributes.getOptionalBoolean('destructive');
      if (destructive !== undefined) {
        parsedAttributes.destructive = destructive;
      }

      const readOnly = attributes.getOptionalBoolean('readOnly');
      if (readOnly !== undefined) {
        parsedAttributes.readOnly = readOnly;
      }

      const idempotent = attributes.getOptionalBoolean('idempotent');
      if (idempotent !== undefined) {
        parsedAttributes.idempotent = idempotent;
      }

      rule.attributes = parsedAttributes;
    }

    return rule;
  });
}

/**
 * Reads a single named MCP server configuration.
 */
export function readMcpServerConfig(
  config: Config,
  key: string,
): McpServerConfig {
  return {
    name: config.getOptionalString('name') ?? key,
    includeRules: parseFilterRules(
      config.getOptionalConfigArray('includeRules') ?? [],
    ),
    excludeRules: parseFilterRules(
      config.getOptionalConfigArray('excludeRules') ?? [],
    ),
  };
}

/**
 * Reads all named MCP server configurations from `mcpActions.servers`.
 *
 * Returns undefined when no servers are configured, in which case the plugin
 * serves a single default server exposing all available actions.
 */
export function readMcpServerConfigs(
  config: Config,
): Record<string, McpServerConfig> | undefined {
  const serversConfig = config.getOptionalConfig('mcpActions.servers');
  if (!serversConfig) {
    return undefined;
  }

  const servers: Record<string, McpServerConfig> = {};
  for (const key of serversConfig.keys()) {
    servers[key] = readMcpServerConfig(serversConfig.getConfig(key), key);
  }
  return servers;
}

// Translates a glob pattern (only `*` is treated as a wildcard) into an
// anchored regular expression, escaping all other regex metacharacters.
function globToRegExp(pattern: string): RegExp {
  const escaped = pattern.replace(/[.*+?^${}()|[\]\\]/g, match =>
    match === '*' ? '.*' : `\\${match}`,
  );
  return new RegExp(`^${escaped}$`);
}

// A rule matches an action when all of its specified conditions match. A rule
// with no conditions matches every action.
function ruleMatchesAction(
  rule: FilterRule,
  action: ActionsServiceAction,
): boolean {
  if (rule.id !== undefined && !globToRegExp(rule.id).test(action.id)) {
    return false;
  }

  if (rule.attributes) {
    for (const [attribute, expected] of Object.entries(rule.attributes)) {
      if (expected === undefined) {
        continue;
      }
      const actual =
        action.attributes[attribute as keyof ActionsServiceAction['attributes']];
      if (actual !== expected) {
        return false;
      }
    }
  }

  return true;
}

/**
 * Filters the given actions according to the include/exclude rules of a server
 * configuration.
 *
 * When both `includeRules` and `excludeRules` are empty, all actions are
 * returned. Otherwise an action is kept when it matches at least one include
 * rule (or there are no include rules) and matches none of the exclude rules.
 */
export function filterActions(
  actions: ActionsServiceAction[],
  serverConfig: McpServerConfig,
): ActionsServiceAction[] {
  const { includeRules, excludeRules } = serverConfig;

  return actions.filter(action => {
    const included =
      includeRules.length === 0 ||
      includeRules.some(rule => ruleMatchesAction(rule, action));
    if (!included) {
      return false;
    }

    const excluded = excludeRules.some(rule => ruleMatchesAction(rule, action));
    return !excluded;
  });
}
