export interface Config {
  /**
   * Configuration for the MCP actions backend plugin.
   */
  mcpActions?: {
    /**
     * When true (the default), tool names exposed via `tools/list` use the
     * full action ID (`pluginId:actionName`). When false, only the short
     * action name is used.
     */
    namespacedToolNames?: boolean;

    /**
     * Named MCP servers. Each key creates a separate endpoint at
     * `/api/mcp-actions/v1/{key}` exposing only the actions that match the
     * configured filter rules.
     */
    servers?: {
      [key: string]: {
        /**
         * A display name for the server.
         */
        name?: string;

        /**
         * Rules describing which actions to include. When empty, all actions
         * are considered included (subject to `excludeRules`).
         */
        includeRules?: Array<{
          /**
           * A glob pattern matched against action IDs, e.g. `catalog:*` or
           * `catalog:get-*`.
           */
          id?: string;
          /**
           * Attribute conditions that an action must match.
           */
          attributes?: {
            destructive?: boolean;
            readOnly?: boolean;
            idempotent?: boolean;
          };
        }>;

        /**
         * Rules describing which actions to exclude. An action matching any
         * exclude rule is removed from the server's tool list.
