function registerActions() {
  const reg = actionsRegistryServiceMock();
  reg.register({
    name: 'get-thing',
    title: 'Get',
    description: 'Get',
    attributes: { readOnly: true, destructive: false, idempotent: true },
    schema: { input: z => z.object({}), output: z => z.object({}) },
    action: async () => ({ output: {} }),
  });
  reg.register({
    name: 'delete-thing',
    title: 'Delete',
    description: 'Delete',
    attributes: { readOnly: false, destructive: true, idempotent: false },
    schema: { input: z => z.object({}), output: z => z.object({}) },
    action: async () => ({ output: {} }),
  });
  return reg;
}

async function connect(server: any) {
  const client = new Client({ name: 't', version: '1.0' });
  const [c, s] = InMemoryTransport.createLinkedPair();
  await Promise.all([client.connect(c), server.connect(s)]);
  return client;
}

describe('scratch', () => {
