      svc.getServer({ credentials: mockCredentials.user() }),
    );
    const res = await client.request({ method: 'tools/list' }, ListToolsResultSchema);
    expect(res.tools.map(t => t.name).sort()).toEqual([
      'test:delete-thing',
      'test:get-thing',
    ]);
  });

  it('short names when disabled', async () => {
    const svc = await McpService.create({
      actions: registerActions(),
